  zero_result_rate DECIMAL(9,6),
  click_through_rate DECIMAL(9,6),
  avg_first_click_position DECIMAL(12,2),
  reformulation_rate DECIMAL(9,6),
  p95_latency_ms DECIMAL(12,2),
  search_to_apply_rate DECIMAL(9,6),
  period_date DATE NOT NULL,
  load_dim_etl_run_id UUID NOT NULL,
  last_refreshed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
