  CONSTRAINT ck_agg_search_quality_daily_zero_result_rate_range CHECK (zero_result_rate IS NULL OR (zero_result_rate >= 0 AND zero_result_rate <= 1)),
  CONSTRAINT ck_agg_search_quality_daily_click_through_rate_range CHECK (click_through_rate IS NULL OR (click_through_rate >= 0 AND click_through_rate <= 1)),
  CONSTRAINT ck_agg_search_quality_daily_reformulation_rate_range CHECK (reformulation_rate IS NULL OR (reformulation_rate >= 0 AND reformulation_rate <= 1)),
  CONSTRAINT ck_agg_search_quality_daily_search_to_apply_rate_range CHECK (search_to_apply_rate IS NULL OR (search_to_apply_rate >= 0 AND search_to_apply_rate <= 1)),
  CONSTRAINT ck_agg_search_quality_daily_counts_nonneg CHECK (searches >= 0 AND zero_result_searches >= 0),
  CONSTRAINT uq_agg_search_quality_daily_grain UNIQUE (dim_date_id, dim_search_surface_id, dim_device_platform_id),
  CONSTRAINT fk_agg_search_quality_daily_dim_date_id FOREIGN KEY (dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_agg_search_quality_daily_dim_search_surface_id FOREIGN KEY (dim_search_surface_id) REFERENCES dim_search_surface (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_agg_search_quality_daily_dim_device_platform_id FOREIGN KEY (dim_device_platform_id) REFERENCES dim_device_platform (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_agg_search_quality_daily_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_agg_search_quality_daily_period_date (period_date) USING HASH WITH (bucket_count = 8)
);
