  version_no INT4 NOT NULL DEFAULT 1,
  valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  valid_to TIMESTAMPTZ,
  is_current BOOL NOT NULL DEFAULT true,
  hash_diff STRING(64) NOT NULL,
  dim_organisation_id UUID NOT NULL,
  posted_by_dim_user_id UUID NOT NULL,
  dim_job_category_id UUID NOT NULL,
  dim_job_type_id UUID NOT NULL,
  dim_location_id UUID,
  dim_demand_type_id UUID NOT NULL,
  job_title STRING(200) NOT NULL,
  status_code STRING(32) NOT NULL,
  seniority_band_code STRING(16),
  min_experience_years INT2,
  max_experience_years INT2,
  salary_min_amount DECIMAL(18,4),
  salary_max_amount DECIMAL(18,4),
  positions_total INT4 NOT NULL DEFAULT 1,
