  is_salary_disclosed BOOL NOT NULL DEFAULT false,
  published_dim_date_id UUID,
  expiry_dim_date_id UUID,
  dim_placeholder_kind_id UUID,
  load_dim_etl_run_id UUID NOT NULL,
  currency_id UUID NOT NULL,
  CONSTRAINT pk_dim_job_requirement PRIMARY KEY (id),
  CONSTRAINT ck_dim_job_requirement_valid_range CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ck_dim_job_requirement_current_flag CHECK ((is_current AND valid_to IS NULL) OR (NOT is_current AND valid_to IS NOT NULL)),
  CONSTRAINT ck_dim_job_requirement_version_positive CHECK (version_no >= 1),
  CONSTRAINT uq_dim_job_requirement_version UNIQUE (job_requirement_id, version_no),
  CONSTRAINT ck_dim_job_requirement_experience_range CHECK (max_experience_years IS NULL OR min_experience_years IS NULL OR max_experience_years >= min_experience_years),
  CONSTRAINT ck_dim_job_requirement_salary_range CHECK (salary_max_amount IS NULL OR salary_min_amount IS NULL OR salary_max_amount >= salary_min_amount),
  CONSTRAINT ck_dim_job_requirement_positions_positive CHECK (positions_total >= 1),
  CONSTRAINT fk_dim_job_requirement_dim_organisation_id FOREIGN KEY (dim_organisation_id) REFERENCES dim_organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
