  CONSTRAINT fk_dim_job_requirement_dim_job_category_id FOREIGN KEY (dim_job_category_id) REFERENCES dim_job_category (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_dim_job_type_id FOREIGN KEY (dim_job_type_id) REFERENCES dim_job_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_dim_location_id FOREIGN KEY (dim_location_id) REFERENCES dim_location (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_dim_demand_type_id FOREIGN KEY (dim_demand_type_id) REFERENCES dim_demand_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_published_dim_date_id FOREIGN KEY (published_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_expiry_dim_date_id FOREIGN KEY (expiry_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_dim_placeholder_kind_id FOREIGN KEY (dim_placeholder_kind_id) REFERENCES dim_placeholder_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_dim_job_requirement_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_dim_job_requirement_job_requirement_id (job_requirement_id) WHERE is_current,
  INDEX idx_dim_job_requirement_job_requirement_id_valid_from (job_requirement_id, valid_from DESC) STORING (is_current),
  INDEX idx_dim_job_requirement_valid_from (valid_from) USING HASH WITH (bucket_count = 16),
  INDEX idx_dim_job_requirement_dim_organisation_id (dim_organisation_id),
  INDEX idx_dim_job_requirement_posted_by_dim_user_id (posted_by_dim_user_id),
  INDEX idx_dim_job_requirement_dim_job_category_id (dim_job_category_id),
  INDEX idx_dim_job_requirement_dim_job_type_id (dim_job_type_id),
  INDEX idx_dim_job_requirement_dim_location_id (dim_location_id),
  INDEX idx_dim_job_requirement_dim_demand_type_id (dim_demand_type_id),
  INDEX idx_dim_job_requirement_published_dim_date_id (published_dim_date_id),
  INDEX idx_dim_job_requirement_expiry_dim_date_id (expiry_dim_date_id)
);
