  CONSTRAINT fk_fact_outreach_recipient_dim_organisation_id FOREIGN KEY (dim_organisation_id) REFERENCES dim_organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_dim_job_requirement_id FOREIGN KEY (dim_job_requirement_id) REFERENCES dim_job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_dim_outreach_type_id FOREIGN KEY (dim_outreach_type_id) REFERENCES dim_outreach_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_dim_channel_id FOREIGN KEY (dim_channel_id) REFERENCES dim_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_sent_dim_date_id FOREIGN KEY (sent_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_delivered_dim_date_id FOREIGN KEY (delivered_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_opened_dim_date_id FOREIGN KEY (opened_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_replied_dim_date_id FOREIGN KEY (replied_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_applied_dim_date_id FOREIGN KEY (applied_dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_outreach_recipient_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_fact_outreach_recipient_outreach_batch_id (outreach_batch_id),
  INDEX idx_fact_outreach_recipient_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_fact_outreach_recipient_dim_candidate_id (dim_candidate_id),
  INDEX idx_fact_outreach_recipient_sender_dim_user_id (sender_dim_user_id),
  INDEX idx_fact_outreach_recipient_sent_dim_date_id (sent_dim_date_id)
);
