  CONSTRAINT fk_fact_profile_download_downloader_dim_user_id FOREIGN KEY (downloader_dim_user_id) REFERENCES dim_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_download_dim_organisation_id FOREIGN KEY (dim_organisation_id) REFERENCES dim_organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_download_dim_job_requirement_id FOREIGN KEY (dim_job_requirement_id) REFERENCES dim_job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_fact_profile_download_event_at (event_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_fact_profile_download_dim_candidate_id (dim_candidate_id),
  INDEX idx_fact_profile_download_downloader_dim_user_id (downloader_dim_user_id)
);
