CREATE TABLE IF NOT EXISTS fact_profile_view (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  event_at TIMESTAMPTZ NOT NULL,
  dim_date_id UUID NOT NULL,
  dim_time_of_day_id UUID NOT NULL,
  load_dim_etl_run_id UUID NOT NULL,
  dim_candidate_id UUID NOT NULL,
  viewer_dim_user_id UUID NOT NULL,
  dim_organisation_id UUID NOT NULL,
  origin_dim_search_surface_id UUID NOT NULL,
  dim_device_platform_id UUID NOT NULL,
  dim_job_requirement_id UUID,
  credits_consumed INT4 NOT NULL DEFAULT 0,
  view_seconds INT4,
  source_ref STRING(100) NOT NULL,
  CONSTRAINT pk_fact_profile_view PRIMARY KEY (id),
  CONSTRAINT uq_fact_profile_view_source_ref UNIQUE (source_ref),
  CONSTRAINT ck_fact_profile_view_counts_nonneg CHECK (credits_consumed >= 0),
  CONSTRAINT fk_fact_profile_view_dim_date_id FOREIGN KEY (dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_dim_time_of_day_id FOREIGN KEY (dim_time_of_day_id) REFERENCES dim_time_of_day (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_dim_candidate_id FOREIGN KEY (dim_candidate_id) REFERENCES dim_candidate (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_viewer_dim_user_id FOREIGN KEY (viewer_dim_user_id) REFERENCES dim_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_dim_organisation_id FOREIGN KEY (dim_organisation_id) REFERENCES dim_organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_origin_dim_search_surface_id FOREIGN KEY (origin_dim_search_surface_id) REFERENCES dim_search_surface (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_dim_device_platform_id FOREIGN KEY (dim_device_platform_id) REFERENCES dim_device_platform (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_profile_view_dim_job_requirement_id FOREIGN KEY (dim_job_requirement_id) REFERENCES dim_job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_fact_profile_view_event_at (event_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_fact_profile_view_dim_organisation_id_dim_date_id (dim_organisation_id, dim_date_id),
  INDEX idx_fact_profile_view_dim_candidate_id (dim_candidate_id),
  INDEX idx_fact_profile_view_viewer_dim_user_id (viewer_dim_user_id)
) WITH (ttl_expiration_expression = '(event_at + INTERVAL ''36 months'')', ttl_job_cron = '@daily');
