CREATE TABLE IF NOT EXISTS fact_wallet_transaction (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  event_at TIMESTAMPTZ NOT NULL,
  dim_date_id UUID NOT NULL,
  dim_time_of_day_id UUID NOT NULL,
  load_dim_etl_run_id UUID NOT NULL,
  wallet_ledger_entry_id UUID NOT NULL,
  dim_organisation_id UUID NOT NULL,
  dim_wallet_entry_type_id UUID NOT NULL,
  actor_dim_user_id UUID,
  dim_job_requirement_id UUID,
  dim_candidate_id UUID,
  credits_delta INT8 NOT NULL,
  balance_after_credits INT8 NOT NULL,
  value_amount DECIMAL(18,4),
  is_reversal BOOL NOT NULL DEFAULT false,
  source_ref STRING(100) NOT NULL,
  currency_id UUID NOT NULL,
  CONSTRAINT pk_fact_wallet_transaction PRIMARY KEY (id),
  CONSTRAINT ck_fact_wallet_transaction_delta_nonzero CHECK (credits_delta <> 0),
  CONSTRAINT ck_fact_wallet_transaction_balance_nonneg CHECK (balance_after_credits >= 0),
  CONSTRAINT uq_fact_wallet_transaction_source_ref UNIQUE (source_ref),
  CONSTRAINT fk_fact_wallet_transaction_dim_date_id FOREIGN KEY (dim_date_id) REFERENCES dim_date (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_dim_time_of_day_id FOREIGN KEY (dim_time_of_day_id) REFERENCES dim_time_of_day (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_dim_organisation_id FOREIGN KEY (dim_organisation_id) REFERENCES dim_organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_dim_wallet_entry_type_id FOREIGN KEY (dim_wallet_entry_type_id) REFERENCES dim_wallet_entry_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_actor_dim_user_id FOREIGN KEY (actor_dim_user_id) REFERENCES dim_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_dim_job_requirement_id FOREIGN KEY (dim_job_requirement_id) REFERENCES dim_job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_dim_candidate_id FOREIGN KEY (dim_candidate_id) REFERENCES dim_candidate (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_fact_wallet_transaction_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_fact_wallet_transaction_event_at (event_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_fact_wallet_transaction_dim_organisation_id_event_at (dim_organisation_id, event_at DESC)
);
