CREATE TABLE IF NOT EXISTS bridge_job_requirement_skill (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  dim_job_requirement_id UUID NOT NULL,
  dim_skill_id UUID NOT NULL,
  weighting_factor DECIMAL(9,6) NOT NULL,
  is_mandatory BOOL NOT NULL DEFAULT true,
  load_dim_etl_run_id UUID NOT NULL,
  CONSTRAINT pk_bridge_job_requirement_skill PRIMARY KEY (id),
  CONSTRAINT ck_bridge_job_requirement_skill_weighting_factor_range CHECK (weighting_factor IS NULL OR (weighting_factor >= 0 AND weighting_factor <= 1)),
  CONSTRAINT uq_bridge_job_requirement_skill_pair UNIQUE (dim_job_requirement_id, dim_skill_id),
  CONSTRAINT fk_bridge_job_requirement_skill_dim_job_requirement_id FOREIGN KEY (dim_job_requirement_id) REFERENCES dim_job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bridge_job_requirement_skill_dim_skill_id FOREIGN KEY (dim_skill_id) REFERENCES dim_skill (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bridge_job_requirement_skill_load_dim_etl_run_id FOREIGN KEY (load_dim_etl_run_id) REFERENCES dim_etl_run (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_bridge_job_requirement_skill_dim_skill_id (dim_skill_id)
);
